### 2. `gitnexus/src/core/search/hybrid-search.ts`
Add new export `selectPipeline()` alongside existing `mergeWithRRF()`:

```typescript
export interface PipelineDecision {
  strategy: 'lexical' | 'semantic';
  confidence: number;
  reason: string;
}

export function classifyQuery(query: string): PipelineDecision {
  // Check for CamelCase tokens
  const hasCamel = /\b[A-Z][a-z]+[A-Z][a-zA-Z]*\b/.test(query);
  // Check for snake_case tokens
  const hasSnake = /\b[a-z][a-z0-9]*(?:_[a-z][a-z0-9]*)+\b/.test(query);
  // Check for compositional potential (3+ content tokens that could compose)
  const contentTokens = query.split(/\s+/)
    .map(t => t.replace(/[?.,!:;()\[\]{}'"\/]/g, '').toLowerCase())
    .filter(t => t.length >= 2 && !STOP_WORDS.has(t));

  if (hasCamel || hasSnake) {
    return { strategy: 'lexical', confidence: 0.95, reason: 'symbol-bearing query' };
  }
  if (contentTokens.length >= 3) {
    return { strategy: 'lexical', confidence: 0.80, reason: 'compositional potential' };
  }
  return { strategy: 'semantic', confidence: 0.60, reason: 'natural language' };
}

export function selectPipeline(
  decision: PipelineDecision,
  bm25Results: BM25SearchResult[],
  semanticResults: SemanticSearchResult[],
  symbolResults: HybridSearchResult[],  // from Phase 2.5 composition
  limit: number
): HybridSearchResult[] {
  // If symbol composition found high-confidence hits, trust them exclusively
  if (symbolResults.length > 0) {
    const topSymbolScore = symbolResults[0].score;
    if (topSymbolScore >= 25.0) {
      return symbolResults.slice(0, limit);
    }
  }

  if (decision.strategy === 'lexical') {
    // Build from BM25 + symbol results, skip semantic
    return buildLexicalResults(bm25Results, symbolResults, limit);
  }

  // Semantic: trust vector if top similarity > 0.65
  if (semanticResults.length > 0 && (1 - semanticResults[0].distance) > 0.65) {
    return buildSemanticResults(semanticResults, limit);
  }

  // Fallback to lexical
  return buildLexicalResults(bm25Results, symbolResults, limit);
}
```

### 3. `gitnexus/src/mcp/local/local-backend.ts`
In the main search orchestration (around Phase 7 where `mergeWithRRF` is called), add a strategy check:
```typescript
const cfg = getConfig().search;
if (cfg.strategy === 'selection' || cfg.strategy === 'auto') {
  const decision = classifyQuery(query);
  results = selectPipeline(decision, bm25Results, semanticResults, symbolResults, limit);
} else {
  results = mergeWithRRF(bm25Results, semanticResults, limit);
}
```

### 4. `gitnexus/src/core/search/stop-words.ts` (new file)
Extract the stop words list into a shared constant used by both `classifyQuery` and existing CamelCase normalization.

## Reference Implementation
See `.overhaul/qa/rca-eval-v2.py` function `_pipeline_selection()` (line 611) for the Python reference. Key behaviors to preserve:
- Symbol composition tries all CamelCase/snake_case variants of content tokens (lengths 5→1)
- Composition matches score `top_score * 5.0` (very high confidence)
- BM25 scores pass through at their raw value
- Selection decision: `has_symbol_match (>= 4x) OR has_composition_match (>= 3x)` → use lexical

